// Normalisasi update Telegram + allow-list (fail-closed: daftar kosong = tolak semua).
const allowed = String($env.TELEGRAM_ALLOWED_CHAT_IDS || '').split(',').map(s => s.trim()).filter(Boolean);
const MAX_FILE_BYTES = 19_000_000; // batas getFile Bot API = 20 MB
const out = [];

for (const item of $input.all()) {
  const u = item.json;
  const cb = u.callback_query;
  const msg = cb ? cb.message : (u.message || u.edited_message);
  const chatId = String(msg?.chat?.id ?? cb?.from?.id ?? '');
  const from = cb?.from ?? msg?.from ?? {};
  const base = {
    update_id: u.update_id,
    chat_id: chatId,
    message_id: msg?.message_id ?? null,
    callback_id: cb?.id ?? null,
  };
  const meta = { update_id: u.update_id, chat_id: chatId, message_id: msg?.message_id ?? null, username: from.username ?? null, first_name: from.first_name ?? null };

  if (!chatId || !allowed.includes(chatId)) { out.push({ json: { ...base, type: 'blocked' } }); continue; }

  if (cb) {
    out.push({ json: { ...base, type: 'callback', payload: { ...meta, kind: 'callback', callback_data: String(cb.data || '').slice(0, 64) } } });
    continue;
  }

  // Media: foto, dokumen (gambar/PDF), voice note, audio
  let media = null;
  if (Array.isArray(msg?.photo) && msg.photo.length) {
    const p = msg.photo[msg.photo.length - 1]; // resolusi terbesar
    media = { kind: 'vision', file_id: p.file_id, file_size: p.file_size ?? 0, mime_type: 'image/jpeg', file_name: 'photo.jpg' };
  } else if (msg?.document) {
    const d = msg.document; const mt = d.mime_type || '';
    if (/^image\/(jpeg|png|webp|gif)$/.test(mt) || mt === 'application/pdf') {
      media = { kind: 'vision', file_id: d.file_id, file_size: d.file_size ?? 0, mime_type: mt, file_name: d.file_name || 'document' };
    } else if (/^audio\//.test(mt)) {
      media = { kind: 'audio', file_id: d.file_id, file_size: d.file_size ?? 0, mime_type: mt, file_name: d.file_name || 'audio' };
    } else {
      out.push({ json: { ...base, type: 'reply', reply: '📎 Jenis file ini belum didukung. Kirim foto, gambar, PDF, atau voice note.' } });
      continue;
    }
  } else if (msg?.voice || msg?.audio) {
    const a = msg.voice || msg.audio;
    media = { kind: 'audio', file_id: a.file_id, file_size: a.file_size ?? 0, mime_type: a.mime_type || 'audio/ogg', file_name: a.file_name || 'voice.ogg', duration: a.duration ?? null };
  }

  if (media) {
    if (media.file_size > MAX_FILE_BYTES) {
      out.push({ json: { ...base, type: 'reply', reply: '⚠️ File terlalu besar (maks ±19 MB untuk bot Telegram).' } });
      continue;
    }
    out.push({ json: { ...base, type: 'media', ...media, caption: (msg.caption ?? '').slice(0, 1000), meta } });
    continue;
  }

  const text = msg?.text ?? null;
  if (text) {
    out.push({ json: { ...base, type: 'text', payload: { ...meta, kind: 'text', source: 'telegram', text: text.slice(0, 4000) } } });
    continue;
  }

  out.push({ json: { ...base, type: 'reply', reply: '🙏 Bot ini menerima teks, foto, dokumen (gambar/PDF), dan voice note. Ketik /help untuk bantuan.' } });
}
return out;

// Bangun request OCR dari file Telegram yang sudah diunduh.
// N8N_OCR_MODE: responses (OpenAI Responses API, default) | chat (Chat Completions + image_url,
// untuk Gemini/OpenAI-compatible). Otomatis chat bila OPENAI_BASE_URL = Gemini.
// Basis URL provider (OpenAI default; Gemini: https://generativelanguage.googleapis.com/v1beta/openai).
const base = String($env.OPENAI_BASE_URL || 'https://api.openai.com/v1').replace(/\/+$/, '');
const isGemini = /^https:\/\/generativelanguage\.googleapis\.com\//.test(base + '/');
const mode = String($env.N8N_OCR_MODE || (isGemini ? 'chat' : 'responses')).toLowerCase();
const src = $('Normalize & Guard').item.json;
const buf = await this.helpers.getBinaryDataBuffer($itemIndex, 'data');
if (buf.length > 15_000_000) throw new Error('File terlalu besar untuk OCR');
const b64 = buf.toString('base64');
const dataUrl = `data:${src.mime_type};base64,${b64}`;
const prompt = 'Ekstrak SEMUA teks dari file ini (foto papan tulis, tulisan tangan, dokumen, screenshot, struk). ' +
  'Tulis dalam bahasa aslinya, rapikan menjadi markdown terstruktur (judul, daftar, tabel bila ada). ' +
  'Tandai bagian yang tidak terbaca dengan [?]. Jangan menambah informasi yang tidak ada. Balas hanya dengan hasil ekstraksi.';
const model = $env.OPENAI_VISION_MODEL || (isGemini ? 'gemini-3.8-flash' : 'gpt-4.1-mini');
if (mode === 'chat') {
  // Gemini menerima gambar (dan PDF) sebagai data URL di image_url.
  return {
    json: {
      ai_url: `${base}/chat/completions`,
      ai_body: {
        model,
        max_tokens: 4000,
        messages: [{ role: 'user', content: [{ type: 'text', text: prompt }, { type: 'image_url', image_url: { url: dataUrl } }] }],
      },
    },
  };
}
const filePart = src.mime_type === 'application/pdf'
  ? { type: 'input_file', filename: src.file_name || 'document.pdf', file_data: dataUrl }
  : { type: 'input_image', image_url: dataUrl, detail: 'high' };
return {
  json: {
    ai_url: `${base}/responses`,
    ai_body: {
      model,
      max_output_tokens: 4000,
      input: [{ role: 'user', content: [{ type: 'input_text', text: prompt }, filePart] }],
    },
  },
};

// Ambil teks hasil OCR dari respons OpenAI lalu susun payload untuk Second Brain.
const src = $('Normalize & Guard').item.json;
const r = $json;
let text = r.output_text;
if (!text && Array.isArray(r.output)) {
  text = r.output.flatMap(o => o.content || []).filter(c => c.type === 'output_text').map(c => c.text).join('\n');
}
const chat = r.choices?.[0]?.message?.content; // Chat Completions (Gemini/OpenAI-compatible)
if (!text && chat) text = Array.isArray(chat) ? chat.map(c => c.text || '').join('') : chat;
text = String(text || '').trim();
return {
  json: {
    payload: {
      ...src.meta,
      kind: 'ocr',
      source: 'ocr',
      text: src.caption || null,          // caption bisa berisi perintah: /task, /note, /inbox
      ocr_text: text.slice(0, 20000),
      file_name: src.file_name,
      mime_type: src.mime_type,
      ocr_model: r.model ?? null,
    },
  },
};

// Telegram voice = .oga; OpenAI/Groq menerima .ogg (format sama).
// Juga tentukan mode transkripsi: N8N_TRANSCRIBE_MODE = transcriptions (default) | chat
// (Chat Completions + input_audio; wajib untuk Gemini, otomatis bila host transkripsi = Gemini).
const item = $input.item;
const b = item.binary.data;
b.fileName = String(b.fileName || 'voice.ogg').replace(/\.oga$/i, '.ogg');
if (!/\.[a-z0-9]+$/i.test(b.fileName)) b.fileName += '.ogg';
const base = String($env.OPENAI_TRANSCRIBE_BASE_URL || $env.OPENAI_BASE_URL || 'https://api.openai.com/v1').replace(/\/+$/, '');
const isGemini = /^https:\/\/generativelanguage\.googleapis\.com\//.test(base + '/');
item.json = { ...item.json, transcribe_mode: String($env.N8N_TRANSCRIBE_MODE || (isGemini ? 'chat' : 'transcriptions')).toLowerCase(), transcribe_base: base };
return item;

// Gemini tidak punya /audio/transcriptions: kirim audio sebagai input_audio (base64) ke Chat Completions.
// Telegram voice = Ogg/Opus; Gemini menerima ogg, webm, mp3, wav, m4a/aac, flac, opus.
const src = $('Normalize & Guard').item.json;
const buf = await this.helpers.getBinaryDataBuffer($itemIndex, 'data');
if (buf.length > 15_000_000) throw new Error('Audio terlalu besar untuk transkripsi');
const sub = String(src.mime_type || 'audio/ogg').split(';')[0].split('/')[1]?.toLowerCase() || 'ogg';
const format = { mpeg: 'mp3', mpga: 'mp3', 'x-wav': 'wav', wave: 'wav', mp4: 'm4a', 'x-m4a': 'm4a', oga: 'ogg' }[sub] || sub;
return {
  json: {
    ai_url: `${$json.transcribe_base}/chat/completions`,
    ai_body: {
      model: $env.OPENAI_TRANSCRIBE_MODEL || 'gemini-3.8-flash',
      messages: [{ role: 'user', content: [
        { type: 'text', text: 'Transcribe this audio verbatim; reply with the transcript only.' },
        { type: 'input_audio', input_audio: { data: buf.toString('base64'), format } },
      ] }],
    },
  },
};

// Susun payload transkripsi voice/audio untuk Second Brain.
const src = $('Normalize & Guard').item.json;
// /audio/transcriptions → { text }; Chat Completions (Gemini) → choices[0].message.content
const chat = $json.choices?.[0]?.message?.content;
const text = String($json.text || (Array.isArray(chat) ? chat.map(c => c.text || '').join('') : chat) || '').trim();
return {
  json: {
    payload: {
      ...src.meta,
      kind: 'voice',
      source: 'voice',
      text: src.caption || null,
      transcript: text.slice(0, 20000),
      duration: src.duration ?? null,
      mime_type: src.mime_type,
    },
  },
};
